// How long the page may take to load and complete the hello handshake before
// the internal-connection error is shown.
constexpr int kHandshakeDeadlineMs = 20000;

constexpr int kHandshakeTimerId = wxID_HIGHEST + 1802;

boost::filesystem::path agent_page_path()
{
    return boost::filesystem::path(resources_dir()) / "jusprin" / "agent" / "index.html";
}

wxString agent_page_url(AgentPageMode mode)
{
    wxString url;
    if (const char* dev = std::getenv("JUSPRIN_AGENT_DEV_URL"); dev != nullptr && *dev != '\0') {
        url = wxString::FromUTF8(dev);
    } else {
        const boost::filesystem::path page = agent_page_path();
        if (!boost::filesystem::exists(page))
            return {};
        url = wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(page.string())));
    }
    if (mode == AgentPageMode::PrinterPanel)
        url += "?panel=printer";
    else if (mode == AgentPageMode::Preferences)
        url += "?panel=preferences";
    else if (mode == AgentPageMode::OrcaImport)
        url += "?panel=orca-import";
    return url;
}

